#!/usr/bin/env python3
# Copyright AStarship <https://astarship.net>.
#
# SyncSeams.py -- Regenerate seam macros + test scaffolding from a seams YAML.
#
# Usage: python3 SyncSeams.py [seams_yaml]
#
# By default, reads seams.yaml from the same directory as this script.
#
# The YAML file is the SINGLE SOURCE OF TRUTH. Never edit the generated files
# by hand -- they are overwritten on the next sync.
#
# It generates (mode-dependent):
#   _Seams.h       -- SEAM macro definitions (PROJECT_CORE=1, ...) + SEAM_N.
#   _Config.h      -- package config: default SEAM + seam list comment.
#   _Main.hxx      -- single-TU entrypoint listing the seam tests.
#   _Tests.hxx     -- test-tree rollup (museworld / asciicrabs modes).
#   NN.<Seam>.hxx  -- per-seam test files.
#   <folder>/01.Core.hxx -- per-module test entry (crabstk hierarchical).
#
# Ordering: seams are numbered 1..N by a topological sort of each seam's
# `depends:` list (a seam is numbered after everything it depends on). When a
# seam has no `depends`, list order breaks ties. The `release` seam must end up
# the highest number.
#
# Schemas (auto-detected in the root yaml):
#   seams:   -- legacy flat: one module, per-seam `module:` fields.
#   modules: -- hierarchical: the root yaml lists MODULES (in build-up order),
#               each pointing at <folder>/_Seams.yaml which carries the
#               legacy seams: schema. Global numbering = module order x
#               module-seam order. See SyncModules().
#
# Modes:
#   crabstk     -- module-based, CTK:: namespace, <Mod>/01.Core.hxx.
#   asciicrabs  -- flat _Seams/, ProjectTest namespace, ASCIICrabs includes.
#   museworld   -- flat root, single TU, MUSETest namespace. The seam test files
#                  live in <root>/_Seams/ and are included directly by
#                  <root>/_Main.hxx (no ASCIICrabs _Seams.hxx / Test.hpp
#                  harness -- that lives inside the ASCIICrabs package).
#
# No third-party dependencies: the YAML subset is parsed in-line (pyyaml is not
# available on the build hosts).

import os
import re
import sys


# ---------------------------------------------------------------------------
# Minimal YAML reader (the subset the seams files use: top-level `key: value`
# scalars, list keys (`seams:`, `modules:`, `preamble:`) whose items are either
# `- key: value` dicts or `- scalar` strings, and `#` comments). No pyyaml
# dependency.
# ---------------------------------------------------------------------------

def ScanSeams(project_dir):
  """Autogenerate the root _Seams.yaml from the numbered files on disk.
  Scans _Seams/<Module>/NN.<Seam>.hxx files, derives seam names from
  filenames, and builds the _CrabsTK<Module><Seam> macro table.
  The numbered files ARE the source of truth — the yaml is a cache."""
  seams_dir = os.path.join(project_dir, "_Seams")
  modules = []
  skip = {"Hatch", "JSX"}  # Python API / removed from main tree
  for entry in sorted(os.listdir(seams_dir)):
    mod_path = os.path.join(seams_dir, entry)
    if not os.path.isdir(mod_path) or entry.startswith("_") or entry in skip:
      continue
    # Find numbered .hxx files: NN.<Seam>.hxx
    files = []
    for f in sorted(os.listdir(mod_path)):
      m = re.match(r"^(\d{2})\.(\w+)\.hxx$", f)
      if m:
        files.append((ISC(m.group(1)), m.group(2), f))
    if not files:
      continue
    files.sort()
    seams = []
    for num, seam_name, fname in files:
      macro = f"_CrabsTK{entry}{seam_name}"
      seams.append({
        "name": seam_name,
        "macro": macro,
        "file": fname,
        "label": f"Testing {entry} {seam_name}...",
      })
    # Release must be the last file
    if seams[-1]["name"] != "Release":
      print(f"  WARN: {entry}: last file is {seams[-1]['file']}, not Release")
    modules.append({
      "name": entry,
      "folder": f"_Seams/{entry}",
      "seams": seams,
    })
    print(f"  {entry}: {len(seams)} seams "
          f"({', '.join(s['file'] for s in seams)})")

  # Build the root yaml
  lines = [
    "# _Seams.yaml — ROOT: module list (autogenerated from files on disk).",
    "# Regenerate: python3 Hatch/SyncSeams.py --scan",
    "# The numbered .hxx files are the source of truth; this yaml is a cache.",
    "",
    "project: CrabsTK",
    "mode: crabstk",
    "release_module: Release",
    "DependsOn: ../ASCIICrabs/_Seams/_Seams.yaml",
    "",
    "modules:",
  ]
  for m in modules:
    lines.append(f"  - name: {m['name']}")
    lines.append(f"    folder: {m['folder']}")
  root_yaml = "\n".join(lines) + "\n"

  # Build per-module yamls (overwriting stale ones from the astar-mary restore)
  for m in modules:
    mod_yaml_lines = [
      f"# {m['name']} module seams (autogenerated from files on disk).",
      f"# Regenerate: python3 Hatch/SyncSeams.py --scan",
      "seams:",
    ]
    for s in m["seams"]:
      mod_yaml_lines.append(f"  - name: {s['name']}")
      mod_yaml_lines.append(f"    macro: {s['macro']}")
      mod_yaml_lines.append(f"    file: {s['file']}")
      mod_yaml_lines.append(f"    label: {s['label']}")
    mod_yaml_path = os.path.join(seams_dir, m["name"], "_Seams.yaml")
    with open(mod_yaml_path, "w") as f:
      f.write("\n".join(mod_yaml_lines) + "\n")

  return root_yaml, modules


def LoadSeams(yaml_path):
  with open(yaml_path, "r") as f:
    lines = f.readlines()

  data = {}
  current = None    # current dict item (seam / module)
  list_key = None   # top-level key owning the open list
  for raw in lines:
    line = raw.rstrip("\n")
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
      continue
    # Top-level "key: value" (no leading dash).
    if not line[0].isspace():
      key, _, val = stripped.partition(":")
      key = key.strip()
      val = val.strip()
      if isinstance(current, dict):
        data[list_key].append(current)
        current = None
      if val == "":
        # A list key (seams: / modules: / preamble: / ...).
        list_key = key
        if key not in data:
          data[key] = []
      else:
        list_key = None
        data[key] = _ParseScalar(val)
      continue
    # List item "- key: value" or "- scalar".
    if stripped.startswith("-"):
      if list_key is None:
        raise SystemExit(f"SyncSeams: list item outside a list: {stripped}")
      rest = stripped[1:].strip()
      if rest and rest[0] in "'\"":
        # Quoted scalar: a colon inside the quotes is data, not a key.
        if isinstance(current, dict):
          data[list_key].append(current)
          current = None
        q = rest[0]
        end = rest.find(q, 1)
        data[list_key].append(rest[1:end] if end != -1 else rest)
        continue
      if rest and ":" in rest:
        if isinstance(current, dict):
          data[list_key].append(current)
        current = {}
        k, _, v = rest.partition(":")
        current[k.strip()] = _ParseScalar(v.strip())
      else:
        if isinstance(current, dict):
          data[list_key].append(current)
          current = None
        data[list_key].append(_ParseScalar(rest))
      continue
    # Continuation key inside a dict item (indented, "key: value").
    if current is not None and ":" in stripped:
      k, _, v = stripped.partition(":")
      current[k.strip()] = _ParseScalar(v.strip())
      continue
    raise SystemExit(f"SyncSeams: unparseable line: {stripped}")
  if isinstance(current, dict):
    data[list_key].append(current)
  data.setdefault("seams", [])
  return data


def _ParseScalar(val):
  if val == "" or val is None:
    return ""
  # Inline list: [a, b, c]
  if val.startswith("[") and val.endswith("]"):
    inner = val[1:-1].strip()
    if not inner:
      return []
    return [_ParseScalar(x.strip()) for x in inner.split(",")]
  # Quoted string.
  if (val.startswith('"') and val.endswith('"')) or (
      val.startswith("'") and val.endswith("'")):
    return val[1:-1]
  # Boolean.
  if val.lower() in ("true", "false"):
    return val.lower() == "true"
  # Integer.
  try:
    return ISC(val)
  except ValueError:
    pass
  return val


# ---------------------------------------------------------------------------
# Ordering: topological sort by `depends`, list order for ties.
# ---------------------------------------------------------------------------

def OrderSeams(seams):
  by_name = {s["name"].upper(): s for s in seams}
  # Kahn's algorithm. depends[] entries are seam names.
  indeg = {s["name"].upper(): 0 for s in seams}
  dependents = {s["name"].upper(): [] for s in seams}
  for s in seams:
    deps = s.get("depends") or []
    if isinstance(deps, str):
      deps = [deps]
    for d in deps:
      d = str(d).upper()
      if d in by_name and d != s["name"].upper():
        indeg[s["name"].upper()] += 1
        dependents[d].append(s["name"].upper())

  # Ready set: zero in-degree. Process in original list order (stable).
  order = []
  ready = [s["name"].upper() for s in seams if indeg[s["name"].upper()] == 0]
  seen = set()
  while ready:
    ready.sort(key=lambda n: [s["name"].upper() for s in seams].index(n))
    n = ready.pop(0)
    if n in seen:
      continue
    seen.add(n)
    order.append(by_name[n])
    for dep in dependents[n]:
      indeg[dep] -= 1
      if indeg[dep] == 0:
        ready.append(dep)
  if len(order) != len(seams):
    cycle = [s["name"] for s in seams if s["name"].upper() not in seen]
    raise SystemExit(f"SyncSeams: cycle in depends: {cycle}")
  return order


def FindRelease(seams, release_name):
  for seam in seams:
    if seam["name"].upper() == release_name.upper():
      return seam
  return seams[-1]


def TestFunctionName(project, seam_name):
  """MUSEWORLD_CORE -> Core. FVM_PARSER -> Parser."""
  parts = seam_name.lower().split("_")
  if len(parts) > 1 and parts[0] == project.lower():
    parts = parts[1:]
  return "".join(p.capitalize() for p in parts)


# ---------------------------------------------------------------------------
# _Seams.h
# ---------------------------------------------------------------------------

def GenerateSeamsH(project, ordered_seams, release_seam):
  lines = [
    "// Copyright AStarship <https://astarship.net>.",
    "//",
    "// AUTO-GENERATED by SyncSeams.py from _Seams.yaml.",
    "// Do not edit by hand -- edit _Seams.yaml and re-run SyncSeams.py.",
    "//",
    "#pragma once",
  ]
  guard = f"{project.upper()}_SEAMS_H"
  lines.append(f"#ifndef {guard}")
  lines.append(f"#define {guard} 1")
  lines.append("")
  for i, seam in enumerate(ordered_seams, 1):
    macro = seam["name"].upper()
    lines.append(f"#define {macro}\t\t\t{i}")
  rel_index = ordered_seams.index(release_seam) + 1
  lines.append(f"// Release seam: {release_seam['name'].upper()} = {rel_index}")
  lines.append("")
  lines.append(f"#define SEAM_N {release_seam['name'].upper()}")
  lines.append(f"#endif  //< {guard}")
  lines.append("")
  return "\n".join(lines)


# ---------------------------------------------------------------------------
# _Config.h (seam-level)
# ---------------------------------------------------------------------------

def GenerateConfigH(project, ordered_seams, release_seam, mode,
                    module_rows=None):
  release_macro = release_seam["name"].upper()
  lines = [
    "// Copyright AStarship <https://astarship.net>.",
    "//",
    "// AUTO-GENERATED by SyncSeams.py from _Seams.yaml.",
    "// Do not edit by hand -- edit _Seams.yaml and re-run SyncSeams.py.",
    "//",
    "// To debug a specific seam, set SEAM to that seam's number. The seam at",
    "// that number runs its full checks; every lower seam is compiled in (and",
    "// its fast checks run) so the module builds layer by layer on top of its",
    "// dependencies. All higher seams are not compiled.",
    "",
    "#pragma once",
    "#ifndef PACKAGE_CONFIGURATION",
    "#define PACKAGE_CONFIGURATION 1",
  ]
  # The seam table comes from the package root _Seams.h (angle-bracket include
  # resolved by the build's include path).
  if mode == "museworld":
    lines.append('#include "../../ASCIICrabs/_ConfigHeader.h"')
    lines.append('#include "../../ASCIICrabs/_ConfigDefault.h"')
    lines.append('#include "../../ASCIICrabs/_ConfigFooter.h"')
  else:
    lines.append("#include <_Seams.h>")
  lines.append("")
  # The in-house single-TU rollup: pulls in every ASCIICrabs implementation
  # (.hxx) needed by the test primitives and the print/streaming layer.
  lines.append('#include "../../ASCIICrabs/_Seams.hxx"')
  lines.append("")
  # The single-TU build needs the ASCIICrabs test primitives (TTestTree,
  # SeamResult, ArgsToString, Test/TestEQ, TestFail) available to the seam
  # files. The declarations come with _Seams.hxx; this re-asserts the
  # templates so the seam files can instantiate TTestTree.
  lines.append('#include "../../ASCIICrabs/Test.hpp"')
  lines.append("")
  lines.append("#ifndef SEAM")
  lines.append(f"#define SEAM {release_macro}")
  lines.append("#endif")
  lines.append("")
  lines.append("/* Seams:")
  for i, seam in enumerate(ordered_seams, 1):
    marker = "  (release)" if seam is release_seam else ""
    lines.append(f"#define {seam['name'].upper()}\t\t\t{i}{marker}")
  lines.append("*/")
  lines.append("")
  # Hierarchical mode: where each module's seams (and code) live. Build
  # metadata -- add a folder to the include path when compiling against a
  # module's headers.
  if module_rows:
    lines.append("/* Module folders (build metadata; paths relative to the project root):")
    width = max(len(name) for name, _ in module_rows)
    for name, folder in module_rows:
      lines.append(f"  {name:<{width}} -> {folder}")
    lines.append("*/")
    lines.append("")
  lines.append("#endif  //< PACKAGE_CONFIGURATION")
  lines.append("")
  return "\n".join(lines)


# ---------------------------------------------------------------------------
# _Main.hxx (single-TU entrypoint)
# ---------------------------------------------------------------------------

def GenerateMainCpp(project, ordered_seams, release_seam, mode):
  project_upper = project.upper()
  if mode == "museworld":
    # Flat root: the .hxx seam files live in <root>/_Seams/ and are included
    # directly (no ASCIICrabs _Seams.hxx / Test.hpp harness).
    return f"""// Copyright AStarship <https://astarship.net>.
//
// AUTO-GENERATED by SyncSeams.py from _Seams.yaml.
// Do not edit by hand -- edit _Seams.yaml and re-run SyncSeams.py.
//
// {project_upper} single translation unit. One .hxx entry, many seams: SEAM
// selects the layer under test (see _Seams.h); every lower seam is compiled
// in and its fast checks run, and the deepest seam's full checks run when
// SEAM == its number. The exe's single .cpp is the generated wrapper that
// includes this file (one .cpp = one .exe). Run: ./MUSEWorld (exit 0 = all
// checks passed).
#include <_Config.h>
#include "_Seams/_Tests.hxx"

using namespace ::_;

ISC main(ISC arg_count, CHA** args) {{
  const CHA* argss = ArgsToString(arg_count, args);
  return SeamResult({project}Tests(argss));
}}
"""
  # Fallback: asciicrabs / crabstk (unchanged legacy behavior).
  if mode == "crabstk":
    modules = {}
    for seam in ordered_seams:
      mod = seam.get("module", project.capitalize())
      modules.setdefault(mod, []).append(seam)
    module_includes = "\n".join(f'#include "{mod}/01.Core.hxx"' for mod in modules)
    test_fns = ", ".join(
        f"{seam.get('module', project.capitalize())}::Test::"
        f"{TestFunctionName(project, seam['name'])}"
        for seam in ordered_seams
    )
    return f"""#include <_Config.h>
#include <_Seams.hxx>
{module_includes}
using namespace CTK;
using namespace CTK;
ISC main(ISC arg_count, CHA** args) {{
  return TTestTree<{test_fns}>(arg_count, args);
}}
"""
  return f"""#include "pch.h"
#include <_Config.h>
#include <_Tests.hxx>
using namespace ::_;
ISC main(ISC arg_count, CHA** args) {{
  return TTestTree<ProjectTests>(arg_count, args);
}}
"""


def GenerateCrabstkMainHxx(project, module_info):
  """Hierarchical crabstk entrypoint: one include per module (in module
  order, folder-relative to _Seams/) + the full test tree. Dormant
  modules are skipped (their 01.Core.hxx exists but is not compiled).

  The tree is a plain TestCase[] passed to SeamTreeTest (the same
  function TTestTree delegates to in ASCIICrabs Test.hpp) rather than
  TTestTree's template parameter pack: GCC (>=13) rejects
  namespace-qualified function names as template arguments for
  function-pointer type parameters (unqualified names work, qualified
  ones do not), and every module test here is qualified."""
  incs = []
  fns = []
  for mi in module_info:
    if not mi["seams"] or mi["dormant"]:
      continue
    rel = os.path.relpath(os.path.join(mi["folder"], "01.Core.hxx"), "_Seams")
    incs.append(f'#include "{rel.replace(os.sep, "/")}"')
    for s in mi["seams"]:
      fns.append(f'CTK::{mi["name"]}::Test::{TestFunctionName(project, s["name"])}')
  module_includes = "\n".join(incs)
  tree_entries = "\n".join(f"  {fn}," for fn in fns)
  return f"""#include "pch.h"
#include <_Config.h>
#include <_Seams.hxx>
// Single-TU implementations the seam tests link against (same set as the
// pre-reorg _Seams/_Main.cpp entry; _Seams.hxx is NOT pulled in here —
// the root config deliberately excludes the full ASCIICrabs machine).
#include <ASCIICrabs/COut.h>
#include <ASCIICrabs/COut.hxx>
#include <ASCIICrabs/AType.hxx>
#include <ASCIICrabs/Array.hxx>
#include <ASCIICrabs/Puff.hxx>
#include <ASCIICrabs/Test.hpp>
#include <ASCIICrabs/Test.hxx>
#include <ASCIICrabs/Stringf.hxx>
{module_includes}
using namespace CTK;
using namespace CTK;
namespace {{
::TestCase CrabsTkTree[] = {{
{tree_entries}
}};
}}
ISC main(ISC arg_count, CHA** args) {{
  return SeamTreeTest(arg_count, args, CrabsTkTree,
                      sizeof(CrabsTkTree) / sizeof(CrabsTkTree[0]));
}}
"""


# ---------------------------------------------------------------------------
# _Tests.hxx (museworld + asciicrabs)
# ---------------------------------------------------------------------------

def GenerateTestsHxx(project, ordered_seams, release_seam, mode):
  if mode not in ("museworld", "asciicrabs"):
    return None
  ns = "MUSETest" if mode == "museworld" else "ProjectTest"
  fn = f"{project}Tests"
  includes = "\n".join(f'#include "{seam["file"]}"' for seam in ordered_seams)
  test_fns = ", ".join(
      f"{ns}::{TestFunctionName(project, seam['name'])}" for seam in ordered_seams
  )
  return f"""// Copyright AStarship <https://astarship.net>.
//
// AUTO-GENERATED by SyncSeams.py from _Seams.yaml.
#include <_Config.h>
//
{includes}
//
#include <Test.hpp>
using namespace ::_;

inline const CHA* {fn}(const CHA* args) {{
  return TTestTree<{test_fns}>(args);
}}
"""


# ---------------------------------------------------------------------------
# Per-seam .hxx files
# ---------------------------------------------------------------------------

def GenerateSeamHxx(project, ordered_seams, release_seam, mode):
  ns = "MUSETest" if mode == "museworld" else "ProjectTest"
  templates = {}
  for i, seam in enumerate(ordered_seams, 1):
    macro = seam["name"].upper()
    fn = TestFunctionName(project, seam["name"])
    label = seam.get("label", f"Testing {seam['name']}...")
    is_release = seam is release_seam
    check_file = seam.get("check_file")
    if not is_release:
      body = f"""  _ATestBegin;
  D_COUT(Headingf("{label}"))"""
      if check_file:
        body += f"\n  MUSETestRun{fn}();"
    else:
      body = f"  // {label} (release seam): runs the full suite once all lower"
      body += f"\n  // seams pass. No checks of its own."

    header = f"""// Copyright AStarship <https://astarship.net>.
//
// AUTO-GENERATED by SyncSeams.py from _Seams.yaml.
#if SEAM >= {macro}
#if SEAM == {macro}
#include "../_Debug.h"
#else
#include "../_Release.h"
#endif
#endif
"""
    if check_file:
      # The check file carries its own includes + a MUSETest namespace that
      # defines MUSETestRun{fn}(). It must be at file scope (not inside the
      # test function), so include it here; the test function below lives in
      # the same MUSETest namespace and calls MUSETestRun{fn}() unqualified.
      content = (
          header
          + f'#if SEAM >= {macro}\n#include "{check_file}"\n#endif\n\n'
          + f"namespace {ns} {{\n\n"
          + f"inline const CHA* {fn}(const CHA* args) {{\n"
          + f"#if SEAM >= {macro}\n{body}\n#endif\n"
          + "  return _NilP;\n}\n\n"
          + f"}}  //< namespace {ns}\n"
      )
    else:
      content = (
          header
          + f"namespace {ns} {{\n\n"
          + f"inline const CHA* {fn}(const CHA* args) {{\n"
          + f"#if SEAM >= {macro}\n{body}\n#endif\n"
          + "  return _NilP;\n}\n\n"
          + f"}}  //< namespace {ns}\n"
      )
    templates[seam["file"]] = content
  return templates


# ---------------------------------------------------------------------------
# crabstk v2: DependsOn base + self-contained _Seams.cpp + numbered .hxx files.
#
# The root yaml carries `DependsOn: <rel path to a base _Seams.yaml>` (the
# ASCIICrabs seam table). The base provides the lower seam numbers (the
# "standard library" layer); this project's modules number on top of it.
# One seam per numbered test file (01.Core.hxx -> Core, 02.<X>.hxx -> <X>,
# NN.Release.hxx -> Release; Release is always the last file). Output is
# minimal: no "AUTO-GENERATED" stubs, no per-seam comment scaffolding.
# ---------------------------------------------------------------------------

def LoadDependsOn(project_dir, depends_on):
  """Resolve a DependsOn path (relative to the root yaml's directory) and
  return the ordered list of base seams from that yaml's `seams:` list."""
  if not depends_on:
    return []
  bpath = os.path.join(project_dir, str(depends_on))
  if not os.path.exists(bpath):
    raise SystemExit(
        f"SyncSeams: DependsOn {str(depends_on)!r} not found at {bpath}")
  bdata = LoadSeams(bpath)
  bseams = bdata.get("seams") or []
  ordered = OrderSeams(bseams)
  # Mark each base seam with its module so the table generator can namespace
  # the includes; base seams are consumed as the standard-library layer.
  # Base seam names ARE the macro names (_CrabsCore, _CrabsIToS, ...) so
  # set macro=name for uniform access downstream.
  for s in ordered:
    s.setdefault("module", bdata.get("project", "Base"))
    s.setdefault("macro", s["name"])
    s["_base"] = True
  return ordered


def TestFunctionNameV2(project, module, seam_name):
  """_CrabsTKDataRecord -> Record (strip the _CrabsTK<Module> prefix to get
  the short C++ test function name the TTestTree instantiates)."""
  prefix = f"_CrabsTK{module}"
  if seam_name.startswith(prefix):
    return seam_name[len(prefix):]
  return seam_name


def GenerateCrabstkSeamsCpp(project, base_seams, module_info, release_seam,
                           release_module):
  """Self-contained _Seams.cpp: macros at the top (base + project), then the
  includes, then main(). No .cpp imported from .cpp -- the entry is the one
  real .cpp; everything it pulls is .hxx/.h."""
  lines = ["// Copyright AStarship <https://astarship.net>.", '#include "pch.h"']
  num = 0
  table = []  # (num, macro, module, is_release)
  for s in base_seams:
    num += 1
    macro = s["macro"]
    table.append((num, macro, s.get("module", "Base"), s is release_seam))
    lines.append(f"#define {macro}\t\t\t{num}")
  for mi in module_info:
    if mi["dormant"]:
      # Dormant: numbered (stable) but excluded from the rollup includes.
      for s in mi["seams"]:
        num += 1
        table.append((num, s["macro"], mi["name"], s is release_seam))
        lines.append(f"#define {s['macro']}\t\t\t{num}")
      continue
    for s in mi["seams"]:
      num += 1
      table.append((num, s["macro"], mi["name"], s is release_seam))
      lines.append(f"#define {s['macro']}\t\t\t{num}")
  release_macro = release_seam["macro"]
  lines.append(f"#define _SeamN {release_macro}")
  lines.append("")
  # Config + core machine + test primitives.
  lines.append("#include <_Config.h>")
  lines.append("#include <ASCIICrabs/_Config.h>")
  lines.append("#include <ASCIICrabs/_Package.hxx>")
  lines.append("#include <ASCIICrabs/Test.hpp>")
  # Module test scaffolding (the test trees). The terminal Release module is
  # the release-tree rollup (Release.hxx), not a test module -- it has no
  # _Seams.hxx dispatch and is excluded here. The test .hxx files pull the
  # module headers directly, so no separate source-rollup include is needed.
  for mi in module_info:
    if mi["dormant"] or mi["name"] == release_module:
      continue
    lines.append(f'#include "{mi["name"]}/_Seams.hxx"')
  lines.append('#include "Release.hxx"')
  lines.append("")
  lines.append("using namespace CTK;")
  lines.append("")
  lines.append("ISC main(ISC arg_count, CHA** args) {")
  lines.append("  const CHA* argss = ArgsToString(arg_count, args);")
  lines.append("  #if _Seam == _SeamN")
  lines.append("  return SeamResult(CTKTest::Release(argss));")
  lines.append("  #else")
  nodes = []
  for mi in module_info:
    if mi["dormant"] or mi["name"] == release_module:
      continue
    nodes.append(f"CTK{mi['name']}Test::Main")
  node_lines = ",\n    ".join(nodes)
  lines.append(f"  return SeamResult(TTestTree<{node_lines}\n  >(argss));")
  lines.append("  #endif")
  lines.append("}")
  lines.append("")
  return "\n".join(lines), table


def GenerateModuleSeamsHxx(module, ordered_m):
  """Per-module _Seams.hxx dispatch: includes the numbered .hxx test files,
  opens CTK<Module>Test, and dispatches Main() to Release at the module's own
  release seam (its last seam), else the non-release test tree."""
  name = module
  incs = "\n".join(f'#include "{s["file"]}"' for s in ordered_m if s.get("file"))
  # The module's own release seam is its last seam.
  rel_macro = ordered_m[-1]["macro"]
  # The non-release test functions, in seam order (Core first), by short name.
  fns = [TestFunctionNameV2(None, name, s["name"]) for s in ordered_m
         if s["macro"] != rel_macro]
  fn_list = ", ".join(fns)
  lines = ["// Copyright AStarship <https://astarship.net>."]
  lines.append(f"#if _Seam >= {rel_macro}")
  lines.append(incs)
  lines.append(f"namespace CTK{name}Test {{")
  lines.append("using namespace ::_;")
  lines.append("using namespace CTK;")
  lines.append("")
  lines.append("inline const CHR* Main(const CHR* args) {")
  lines.append(f"#if _Seam == {rel_macro}")
  lines.append("  return Release(args);")
  lines.append("#else")
  lines.append(f"  return TTestTree<{fn_list}>(args);")
  lines.append("#endif")
  lines.append("}")
  lines.append("")
  lines.append(f"}}  //< namespace CTK{name}Test")
  lines.append("#endif")
  lines.append("")
  return "\n".join(lines)


def GenerateCrabstkCMakeLists(project, module_info, release_module):
  """Autogenerated _Seams/CMakeLists.txt: builds the main CrabsTK binary from
  _Seams/_Seams.cpp, plus one standalone binary per module from
  _Seams/<Mod>/_Seams.cpp. Each module binary lives in its own build dir
  (build/<Mod>/). The CMakeLists is fully generated — never edit by hand."""
  lines = [
    "cmake_minimum_required (VERSION 2.6)",
    f"project ({project})",
    "# Autogenerated by SyncSeams.py -- do not edit by hand.",
    "# One .cpp = one binary. The main entry is _Seams.cpp (this directory);",
    "# each module also gets a standalone binary from <Mod>/_Seams.cpp.",
  ]
  get_root = 'get_filename_component (CRABSTK_ROOT "${CMAKE_CURRENT_SOURCE_DIR}/.." ABSOLUTE)'
  get_parent = 'get_filename_component (CRABSTK_PARENT "${CRABSTK_ROOT}/.." ABSOLUTE)'
  lines.append(get_root)
  lines.append(get_parent)
  lines.append("")

  # Main binary: _Seams/_Seams.cpp -> build/generated/_Seams.cpp wrapper.
  lines.append('# Main binary: the full test tree.')
  lines.append('file (MAKE_DIRECTORY "${CMAKE_BINARY_DIR}/generated")')
  lines.append('file (WRITE "${CMAKE_BINARY_DIR}/generated/_Seams.cpp"')
  lines.append('  "// Generated by CMake. Single-TU wrapper.\\n"')
  lines.append('  "#include \\"${CMAKE_CURRENT_SOURCE_DIR}/_Seams.cpp\\"\\n")')
  lines.append('add_executable(CrabsTK "${CMAKE_BINARY_DIR}/generated/_Seams.cpp")')
  lines.append('target_include_directories(CrabsTK PRIVATE')
  lines.append('  "${CMAKE_CURRENT_SOURCE_DIR}"')
  lines.append('  "${CRABSTK_ROOT}"')
  lines.append('  "${CRABSTK_PARENT}/ASCIICrabs"')
  lines.append('  "${CRABSTK_PARENT}"')
  lines.append(")")
  lines.append("set_target_properties(CrabsTK PROPERTIES")
  lines.append("  CXX_STANDARD 23")
  lines.append("  CXX_STANDARD_REQUIRED ON")
  lines.append("  CXX_EXTENSIONS ON")
  lines.append(")")
  lines.append("")

  # Per-module standalone binaries.
  for mi in module_info:
    if mi["dormant"] or not mi["seams"] or mi["name"] == release_module:
      continue
    name = mi["name"]
    target = f"CrabsTK_{name}"
    src = f"${{CMAKE_CURRENT_SOURCE_DIR}}/{name}/_Seams.cpp"
    lines.append(f"# {name} module: standalone binary.")
    lines.append(f'file (MAKE_DIRECTORY "${{CMAKE_BINARY_DIR}}/{name}")')
    lines.append(f'file (WRITE "${{CMAKE_BINARY_DIR}}/{name}/_Seams.cpp"')
    lines.append(f'  "// Generated by CMake. Single-TU wrapper.\\n"')
    lines.append(f'  "#include \\"{src}\\"\\n")')
    lines.append(f'add_executable({target} "${{CMAKE_BINARY_DIR}}/{name}/_Seams.cpp")')
    lines.append(f'target_include_directories({target} PRIVATE')
    lines.append(f'  "${{CMAKE_CURRENT_SOURCE_DIR}}/{name}"')
    lines.append(f'  "${{CMAKE_CURRENT_SOURCE_DIR}}"')
    lines.append(f'  "${{CRABSTK_ROOT}}"')
    lines.append(f'  "${{CRABSTK_PARENT}}/ASCIICrabs"')
    lines.append(f'  "${{CRABSTK_PARENT}}"')
    lines.append(")")
    lines.append(f"set_target_properties({target} PROPERTIES")
    lines.append("  CXX_STANDARD 23")
    lines.append("  CXX_STANDARD_REQUIRED ON")
    lines.append("  CXX_EXTENSIONS ON")
    lines.append(")")
    lines.append("")

  return "\n".join(lines) + "\n"


def GenerateModuleSeamsCpp(project, base_seams, module_info, mi, release_seam):
  """Per-module _Seams.cpp: a standalone binary that tests ONLY this module's
  seam tree. Same global macro table as the main _Seams.cpp (seam numbers are
  assigned by module order in the root yaml, so they must match globally), but
  the includes pull only this module's _Seams.hxx and main() calls only this
  module's Main. One .cpp per binary — a separate binary from the main
  _Seams.cpp."""
  name = mi["name"]
  lines = ["// Copyright AStarship <https://astarship.net>.", '#include "pch.h"']
  num = 0
  for s in base_seams:
    num += 1
    lines.append(f"#define {s['macro']}\t\t\t{num}")
  for other in module_info:
    for s in other["seams"]:
      num += 1
      lines.append(f"#define {s['macro']}\t\t\t{num}")
  lines.append(f"#define _SeamN {release_seam['macro']}")
  lines.append("")
  lines.append("#include <_Config.h>")
  lines.append("#include <ASCIICrabs/_Config.h>")
  lines.append("#include <ASCIICrabs/_Package.hxx>")
  lines.append("#include <ASCIICrabs/Test.hpp>")
  lines.append('#include "_Seams.hxx"')
  lines.append("")
  lines.append("using namespace CTK;")
  lines.append("")
  lines.append("ISC main(ISC arg_count, CHA** args) {")
  lines.append("  const CHA* argss = ArgsToString(arg_count, args);")
  lines.append(f"  return SeamResult(CTK{name}Test::Main(argss));")
  lines.append("}")
  lines.append("")
  return "\n".join(lines)


def GenerateNumberedHxx(module, seam, release_seam, is_release):
  """One numbered .hxx test file per seam. Minimal: copyright, config
  include, the debug/release gate, the test function. No AUTO-GENERATED
  stub, no SYNC-KEEP markers, no placeholder comments."""
  name = module
  macro = seam["macro"]
  fn = TestFunctionNameV2(None, name, seam["name"])
  lines = ["// Copyright AStarship <https://astarship.net>.", "#pragma once"]
  if is_release:
    lines.append('#include "../_Config.h"')
    lines.append(f"namespace CTK{name}Test {{")
    lines.append(f"inline const CHA* {fn}(const CHA* args) {{")
    lines.append(f"#if _Seam == {macro}")
    lines.append("  // Release seam: runs the full module tree.")
    lines.append("#endif")
    lines.append("  return _NilP;")
    lines.append("}")
    lines.append(f"}}  //< namespace CTK{name}Test")
  else:
    lines.append('#include "../_Config.h"')
    lines.append(f"#if _Seam == {macro}")
    lines.append("#include <ASCIICrabs/_Debug.h>")
    lines.append("#else")
    lines.append("#include <ASCIICrabs/_Release.h>")
    lines.append("#endif")
    lines.append("#include <ASCIICrabs/Test.h>")
    lines.append(f"namespace CTK{name}Test {{")
    lines.append(f"inline const CHA* {fn}(const CHA* args) {{")
    lines.append(f"#if _Seam >= {macro}")
    lines.append("  _ATestBegin;")
    lines.append("#endif")
    lines.append("  return _NilP;")
    lines.append("}")
    lines.append(f"}}  //< namespace CTK{name}Test")
  lines.append("")
  return "\n".join(lines)


def SyncCrabstk(project_dir, data, mode, output_dir=None):
  """crabstk v2 entry: DependsOn base + modules, one seam per numbered file,
  self-contained _Seams.cpp + per-module _Seams.hxx + numbered .hxx files.

  output_dir: if set, generated files go here instead of project_dir. This
  is the smoke-test path — the real in-tree .hxx test code is never clobbered;
  the generated skeletons are emitted to the smoke dir for inspection."""
  project = str(data.get("project", "PROJECT"))
  modules = data.get("modules") or []
  if not modules:
    raise SystemExit("SyncSeams: crabstk mode requires a non-empty modules: list")
  release_module = str(data.get("release_module", modules[-1]["name"]))
  # The release module is the terminal rollup (Release.hxx) — it's not a
  # numbered-file module, so it won't be in the scanned module list. Only
  # validate the check if the release module IS in the list (legacy layout).
  if release_module in [m["name"] for m in modules] and modules[-1]["name"] != release_module:
    raise SystemExit(
        f"SyncSeams: release module {release_module} must be LAST "
        f"(last is {modules[-1]['name']}).")

  base_seams = LoadDependsOn(project_dir, data.get("DependsOn"))

  module_info = []
  all_seams = []
  seen = {}
  for m in modules:
    if not isinstance(m, dict) or not m.get("name"):
      raise SystemExit(f"SyncSeams: a module in modules: has no name: {m}")
    name = str(m["name"])
    folder = m.get("folder") or f"_Seams/{name}"
    folder = str(folder)
    mpath = os.path.join(project_dir, folder, "_Seams.yaml")
    mseams = []
    if os.path.exists(mpath):
      mdata = LoadSeams(mpath)
      mseams = mdata.get("seams") or []
    else:
      mdata = {}
    for s in mseams:
      s["module"] = name
    ordered_m = OrderSeams(mseams)
    for s in ordered_m:
      # v2: the macro (_CrabsTK<Module><Seam>) is the unique key — seam
      # names (Core, Release) repeat across modules.
      key = s.get("macro", f"_CrabsTK{name}{s['name']}").upper()
      if key in seen:
        raise SystemExit(
            f"SyncSeams: duplicate seam macro {key} (modules {seen[key]} "
            f"and {name}).")
      seen[key] = name
      all_seams.append(s)
    module_info.append({
        "name": name,
        "folder": folder,
        "seams": ordered_m,
        "dormant": BOL(m.get("dormant")),
        "mdata": mdata,
    })

  # The release seam is the LAST seam overall. If the release module is in
  # the module list (legacy layout), use its last seam. Otherwise (scanned
  # layout where Release is the terminal rollup, not a numbered-file module),
  # use the last seam of the last module.
  release_mod = next((mi for mi in module_info if mi["name"] == release_module), None)
  if release_mod and release_mod["seams"]:
    release_seam = release_mod["seams"][-1]
  elif all_seams:
    release_seam = all_seams[-1]
  else:
    release_seam = None
  if release_seam is None:
    raise SystemExit("SyncSeams: no release seam found")

  seams_dir = os.path.join(output_dir or project_dir, "_Seams")
  os.makedirs(seams_dir, exist_ok=True)
  written = []

  def Write(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True) if os.path.dirname(
        path) else None
    with open(path, "w") as f:
      f.write(content)
    written.append(os.path.relpath(path, output_dir or project_dir))

  # 1. The self-contained _Seams.cpp (macros at top + includes + main).
  cpp, table = GenerateCrabstkSeamsCpp(project, base_seams, module_info,
                                       release_seam, release_module)
  Write(os.path.join(seams_dir, "_Seams.cpp"), cpp)

  # 1b. The autogenerated CMakeLists.txt (main binary + per-module binaries).
  Write(os.path.join(seams_dir, "CMakeLists.txt"),
        GenerateCrabstkCMakeLists(project, module_info, release_module))

  # 2. Per-module _Seams.hxx dispatch + per-module _Seams.cpp (standalone
  #    binary for isolated module testing). Numbered .hxx test files are
  #    user-owned — the generator does NOT touch them.
  for mi in module_info:
    if not mi["seams"] or mi["dormant"]:
      continue
    mod_dir = os.path.join(output_dir or project_dir, mi["folder"])
    os.makedirs(mod_dir, exist_ok=True)
    Write(os.path.join(mod_dir, "_Seams.hxx"),
          GenerateModuleSeamsHxx(mi["name"], mi["seams"]))
    Write(os.path.join(mod_dir, "_Seams.cpp"),
          GenerateModuleSeamsCpp(project, base_seams, module_info, mi,
                                 release_seam))

  out_label = f" -> {output_dir}" if output_dir else ""
  print(f"Synced {len(written)} files (crabstk v2, base={len(base_seams)}){out_label}:")
  for w in written:
    print(f"  {w}")
  print(f"\nSeam table (base {len(base_seams)} + project):")
  for num, macro, mod, is_rel in table:
    marker = "  (release)" if is_rel else ""
    print(f"  {num:>3}. {macro:<28} [{mod}]{marker}")


# ---------------------------------------------------------------------------
# Hierarchical modules: schema (root yaml with `modules:`)
# ---------------------------------------------------------------------------
# Root _Seams.yaml lists MODULES in build-up order; each module points at
# <folder>/_Seams.yaml (the legacy seams: schema). Global numbering =
# module order x module-seam order. The release module must be last; a module
# may be flagged dormant (numbered + scaffolded, but not compiled into the
# rollup). 01.Core.hxx is merge-safe: user code between
# // SYNC-KEEP-BEGIN / // SYNC-KEEP-END is preserved byte-for-byte; on the
# first sync, markers are seeded around any existing non-placeholder body,
# and a frozen leading /* ... */ header block is kept.

def SyncModules(project_dir, data, mode):
  project = str(data.get("project", "PROJECT"))
  if "seams" in data and data["seams"]:
    raise SystemExit(
        "SyncSeams: root yaml has both modules: and seams: -- pick one "
        "(modules: for hierarchical, seams: for legacy flat).")
  modules = data.get("modules") or []
  if not modules:
    raise SystemExit("SyncSeams: modules: list is empty")
  for m in modules:
    if not isinstance(m, dict) or not m.get("name"):
      raise SystemExit(f"SyncSeams: a module in modules: has no name: {m}")
  release_module = str(data.get("release_module", modules[-1]["name"]))
  if modules[-1]["name"] != release_module:
    raise SystemExit(
        f"SyncSeams: release module {release_module} must be the LAST entry "
        f"in modules: (last is {modules[-1]['name']}).")

  module_info = []
  all_seams = []
  seen = {}
  for m in modules:
    name = str(m["name"])
    folder = m.get("folder") or f"_Seams/{name}"
    if os.path.isabs(str(folder)):
      raise SystemExit(f"SyncSeams: module {name}: folder must be relative")
    folder = str(folder)
    mpath = os.path.join(project_dir, folder, "_Seams.yaml")
    if not os.path.exists(mpath):
      raise SystemExit(
          f"SyncSeams: module {name}: {os.path.relpath(mpath, project_dir)} "
          f"not found.")
    mdata = LoadSeams(mpath)
    mseams = mdata.get("seams") or []
    for s in mseams:
      s["module"] = name
    ordered_m = OrderSeams(mseams)
    for s in ordered_m:
      key = s["name"].upper()
      if key in seen:
        raise SystemExit(
            f"SyncSeams: duplicate seam name {key} (modules "
            f"{seen[key]} and {name}).")
      seen[key] = name
      all_seams.append(s)
    module_info.append({
        "name": name,
        "folder": folder,
        "seams": ordered_m,
        "dormant": BOL(m.get("dormant")),
        "mdata": mdata,
    })

  if not all_seams:
    raise SystemExit("SyncSeams: no seams found in any module")

  # Global depends validation: every dep must exist and sit STRICTLY earlier
  # in the global table (a forward or same-module-later dep is a hard error;
  # per-module Kahn already ordered same-module deps correctly).
  for i, s in enumerate(all_seams):
    deps = s.get("depends") or []
    if isinstance(deps, str):
      deps = [deps]
    for d in deps:
      d = str(d).upper()
      if d not in seen:
        raise SystemExit(
            f"SyncSeams: module {s['module']}: seam {s['name']} depends on "
            f"unknown seam {d}.")
      dep_idx = next(j for j, x in enumerate(all_seams)
                     if x["name"].upper() == d)
      if dep_idx >= i:
        raise SystemExit(
            f"SyncSeams: module {s['module']}: seam {s['name']} depends on "
            f"{d}, which is not earlier in the global table.")

  release_mod = next(mi for mi in module_info
                     if mi["name"] == release_module)
  release_seam = release_mod["seams"][-1] if release_mod["seams"] \
      else all_seams[-1]
  if not release_mod["seams"]:
    print(f"SyncSeams: note: release module {release_module} has no seams; "
          f"using {all_seams[-1]['name'].upper()} as the release seam.")

  seams_dir = os.path.join(project_dir, "_Seams")
  os.makedirs(seams_dir, exist_ok=True)
  written = []

  def Write(root, rel_path, content):
    path = os.path.join(root, rel_path)
    os.makedirs(os.path.dirname(path), exist_ok=True) if os.path.dirname(
        path) else None
    with open(path, "w") as f:
      f.write(content)
    written.append(os.path.relpath(path, project_dir))

  # Seam table: project root + _Seams/ (matches the flat crabstk layout).
  table = GenerateSeamsH(project, all_seams, release_seam)
  Write(project_dir, "_Seams.h", table)
  Write(seams_dir, "_Seams.h", table)
  Write(seams_dir, "_Config.h", GenerateConfigH(
      project, all_seams, release_seam, mode,
      module_rows=[(mi["name"], mi["folder"]) for mi in module_info]))
  Write(seams_dir, "_Main.hxx", GenerateCrabstkMainHxx(project, module_info))
  for mi in module_info:
    if not mi["seams"]:
      continue
    Write(project_dir, f"{mi['folder']}/01.Core.hxx",
          GenerateModuleCoreHxx(project, project_dir, mi, release_seam))

  print(f"Synced {len(written)} files from {os.path.basename(__file__)} "
        f"({len(module_info)} modules):")
  for w in written:
    print(f"  {w}")
  print(f"\nSeam table (module order x depends):")
  for i, seam in enumerate(all_seams, 1):
    marker = "  (release)" if seam is release_seam else ""
    dormant = "  (dormant)" if seam["module"] == release_module and \
        next(mi for mi in module_info if mi["name"] == seam["module"])[
            "dormant"] else ""
    print(f"  {i}. {seam['name'].upper()} = {i}  [{seam['module']}]{marker}")


# ---------------------------------------------------------------------------
# Merge-safe <folder>/01.Core.hxx
# ---------------------------------------------------------------------------

def ExtractLeadingComment(text):
  """Return the frozen leading /* ... */ block (MPL/Doxygen header) if the
  file carries one above its first directive, else None."""
  lines = text.splitlines()
  first_code = None
  for i, ln in enumerate(lines):
    s = ln.strip()
    if s.startswith("#") or s.startswith("namespace") or s.startswith("using"):
      first_code = i
      break
  window = lines[:first_code] if first_code is not None else lines
  for i, ln in enumerate(window):
    if ln.strip().startswith("/*"):
      j = i
      while j < len(window) and "*/" not in window[j]:
        j += 1
      if j < len(window):
        return window[i:j + 1]
  return None


_FN_RE = re.compile(r"^inline const CHA\* (\w+)\(const CHA\* args\) \{\s*$")


def ExtractFunctionBodies(text):
  """fn name -> lines between its opening brace and its closing brace."""
  bodies = {}
  lines = text.splitlines()
  i = 0
  while i < len(lines):
    m = _FN_RE.match(lines[i])
    if m:
      fn = m.group(1)
      i += 1
      body = []
      while i < len(lines) and lines[i].strip() != "}":
        body.append(lines[i])
        i += 1
      bodies[fn] = body
    i += 1
  return bodies


def SeedBody(fn_lines, is_release):
  """User lines to place between the SYNC-KEEP markers for this function.

  Marker-present files keep their block byte-for-byte. First-run files get
  markers seeded around the non-placeholder remainder of the old body (the
  skeleton lines -- gating, _ATestBegin, D_COUT, placeholder, returns --
  are regenerated, everything else is user code)."""
  if fn_lines and "// SYNC-KEEP-BEGIN" in fn_lines and \
      "// SYNC-KEEP-END" in fn_lines:
    b = fn_lines.index("// SYNC-KEEP-BEGIN")
    e = fn_lines.index("// SYNC-KEEP-END")
    return list(fn_lines[b + 1:e])
  if fn_lines:
    kept = []
    for ln in fn_lines:
      s = ln.strip()
      if not s:
        continue
      if s.startswith("#if SEAM") or s.startswith("#elif SEAM") \
          or s == "#endif":
        continue
      if s == "_ATestBegin;":
        continue
      if s.startswith("D_COUT(Headingf("):
        continue
      if s == "// Your test code here.":
        continue
      if re.match(r"^return\b", s):
        continue
      kept.append(ln)
    if kept:
      return kept
  if is_release:
    return []
  return ["  // Your test code here."]


def GenerateModuleCoreHxx(project, project_dir, mi, release_seam):
  name, folder = mi["name"], mi["folder"]
  seams = mi["seams"]
  existing = ""
  p = os.path.join(project_dir, folder, "01.Core.hxx")
  if os.path.exists(p):
    with open(p, "r") as f:
      existing = f.read()
  header = ExtractLeadingComment(existing)
  bodies = ExtractFunctionBodies(existing)
  preamble = [str(x) for x in (mi["mdata"].get("preamble") or [])]

  lines = [
    "// Copyright AStarship <https://astarship.net>.",
    "//",
    f"// AUTO-GENERATED by SyncSeams.py from {folder}/_Seams.yaml.",
    "// Do not edit by hand -- edit _Seams.yaml and re-run SyncSeams.py.",
    "// Code between the SYNC-KEEP markers is preserved on every sync.",
  ]
  if header:
    lines.append("")
    lines.extend(header)
  lines += ["#pragma once", "#include <_Config.h>", ""]
  for s in seams:
    macro = s["name"].upper()
    lines.append(f"#if SEAM == {macro}")
    lines.append("#include <ASCIICrabs/_Debug.h>")
    lines.append(f"#elif SEAM > {macro}")
    lines.append("#include <ASCIICrabs/_Release.h>")
    lines.append("#endif")
  lines.append("#include <ASCIICrabs/Test.h>")
  lines.append("")
  lines.extend(preamble)
  if preamble:
    lines.append("")
  lines += ["using namespace CTK;", "namespace CTK {",
            f"namespace {name} {{", "namespace Test {", ""]
  legacy_core_consumed = False
  for s in seams:
    macro = s["name"].upper()
    fn = TestFunctionName(project, s["name"])
    label = s.get("label") or f"Testing {s['name']}..."
    is_release = s is release_seam
    old = bodies.get(fn)
    if old is None and fn != "Core" and not legacy_core_consumed:
      # Legacy files named their single entry point `Core`; seed its body
      # into the first function that has no exact-name match, once.
      old = bodies.get("Core")
      legacy_core_consumed = True
    kept = SeedBody(old, is_release)
    lines.append(f"inline const CHA* {fn}(const CHA* args) {{")
    if is_release:
      lines.append(f"#if SEAM == {macro}")
      lines.append("// SYNC-KEEP-BEGIN")
      lines.extend(kept)
      lines.append("// SYNC-KEEP-END")
      lines.append("#endif")
    else:
      lines.append(f"#if SEAM >= {macro}")
      lines.append("  _ATestBegin;")
      lines.append(f'  D_COUT(Headingf("{label}"));')
      lines.append("")
      lines.append("// SYNC-KEEP-BEGIN")
      lines.extend(kept)
      lines.append("// SYNC-KEEP-END")
      lines.append("#endif")
    lines.append("  return _NilP;")
    lines.append("}")
    lines.append("")
  lines += ["}  //< namespace Test", f"}}  //< namespace {name}",
            "}  //< namespace CTK", ""]
  return "\n".join(lines)


# ---------------------------------------------------------------------------
# igeek mode — scaffolding-only sync for the iGeek seam tree.
#
# iGeek is hierarchical (modules: schema) but shaped differently from crabstk:
#   * Seam numbering CONTINUES from the ASCIICrabs base (CRABS_* = 1..base), so
#     the first iGeek seam is base+1, not 1. The project's _Seams.h includes
#     the ASCIICrabs seam table so the base macros (CRABS_*) are visible.
#   * Namespaces: the RL core lives in `namespace iGeek`; each world's test
#     entry is `<World>Test::<World>` (a TTestTree dispatch fn), not
#     `CTK::<World>::Test::<Seam>`.
#   * Layout: a single _Seams/_Main.cpp TU; _Seams/_Tests.hxx is the rollup
#     tree that includes the RL core (01.Core.hxx/02.Release.hxx under Core/)
#     plus every world's <World>/_Tests.hxx dispatch stub.
#   * SCAFFOLDING-ONLY: this mode regenerates the seam table, the config, the
#     rollup includes, and the per-world _Tests.hxx dispatch stubs. It does NOT
#     regenerate the user-owned 01.Core.hxx / 02.Release.hxx test bodies —
#     those carry the real test code and are preserved byte-for-byte.
# ---------------------------------------------------------------------------

def GenerateIgeekSeamsH(project, ordered_seams, release_seam, base_offset):
  """_Seams.h for igeek: includes the ASCIICrabs seam table (for the CRABS_*
  base macros), then numbers the project's own seams starting at base+1."""
  lines = [
    "// Copyright AStarship <https://astarship.net>.",
    "//",
    "// AUTO-GENERATED by SyncSeams.py from _Seams.yaml (igeek mode).",
    "// Do not edit by hand -- edit _Seams.yaml and re-run SyncSeams.py.",
    "//",
    "// The iGeek seam table builds on the ASCIICrabs seam table",
    f"// (CRABS_* = 1..{base_offset}). iGeek's own seams start at {base_offset + 1}.",
    "// A single -DSEAM=<n> selects exactly one seam; a world's RELEASE is its",
    "// official output.",
    "#pragma once",
  ]
  guard = f"{project.upper()}_SEAMS_H"
  lines.append(f"#ifndef {guard}")
  lines.append(f"#define {guard} 1")
  lines.append("")
  lines.append('#include "../../ASCIICrabs/_Seams/_Seams.h"')
  lines.append("")
  for i, seam in enumerate(ordered_seams):
    num = base_offset + i + 1
    macro = seam["name"].upper()
    lines.append(f"#define {macro}\t\t\t{num}")
  rel_num = base_offset + ordered_seams.index(release_seam) + 1
  lines.append(f"// Release seam: {release_seam['name'].upper()} = {rel_num}")
  lines.append("")
  lines.append(f"#define SEAM_N {release_seam['name'].upper()}")
  lines.append(f"#endif  //< {guard}")
  lines.append("")
  return "\n".join(lines)


def GenerateIgeekConfigH(project, ordered_seams, release_seam, base_offset):
  """_Config.h for igeek: pulls the ASCIICrabs config, then #undefs SEAM
  (ASCIICrabs's _ConfigFooter.h sets SEAM=_CrabsRelease with no guard) and
  redefines it to SEAM_N (the full sown tree). The seam table lives in
  _Seams.cpp (defined before any includes), not in a separate _Seams.h."""
  release_macro = release_seam["name"].upper()
  lines = [
    "// Copyright AStarship <https://astarship.net>.",
    "//",
    "// AUTO-GENERATED by SyncSeams.py from _Seams.yaml (igeek mode).",
    "// Do not edit by hand -- edit _Seams.yaml and re-run SyncSeams.py.",
    "//",
    "#pragma once",
    f"#ifndef {project.upper()}_SEAMS_CONFIG",
    f"#define {project.upper()}_SEAMS_CONFIG",
    '#include "../../ASCIICrabs/_Config.h"',
    "// #undef SEAM: ASCIICrabs/_ConfigFooter.h sets SEAM=_CrabsRelease with",
    "// no guard. Redefine to SEAM_N so every IGEEK_* gate evaluates true.",
    "#undef SEAM",
    "#define SEAM SEAM_N",
    "",
    f"/* Seams (iGeek block, on top of the ASCIICrabs base 1..{base_offset}):",
  ]
  for i, seam in enumerate(ordered_seams):
    num = base_offset + i + 1
    marker = "  (release)" if seam is release_seam else ""
    lines.append(f"#define {seam['name'].upper()}\t\t\t{num}{marker}")
  lines.append("*/")
  lines.append(f"#endif  //< {project.upper()}_SEAMS_CONFIG")
  lines.append("")
  return "\n".join(lines)


def GenerateIgeekSeamsCpp(project, ordered_seams, release_seam, base_offset,
                          module_info, project_dir):
  """_Seams/_Seams.cpp for igeek: the single translation unit. Contains:
  1. pch include
  2. The CRABS_* base macros (1..base_offset) — inlined from the ASCIICrabs
     seam table so the TU is self-contained (no separate _Seams.h).
  3. The IGEEK_* project macros (base_offset+1 .. base_offset+len)
  4. SEAM_N = the release macro
  5. _Config.h + ASCIICrabs _Config.h + _Seams.hxx + Test.hpp
  6. Each module's <Mod>/_Seams.hxx (user-owned, NOT regenerated)
  7. Release.hxx (the release-tree rollup, user-owned)
  8. main(): SeamResult(iGeekTest::iGeekRelease) at SEAM_N, else
     TTestTree<CoreMain, <World>Test::<World>, ...>
  The per-module _Seams.hxx files are user-owned (they carry real test
  dispatch code, includes, and world-specific engine pulls). SyncSeams.py
  does NOT regenerate them."""
  lines = [
    "// Copyright AStarship <https://astarship.net>.",
    '#include "pch.h"',
  ]
  # CRABS_* base macros (1..base_offset).
  asc_seams = os.path.join(project_dir, "..", "ASCIICrabs",
                           "_Seams", "_Seams.cpp")
  crabs_macros = []
  if os.path.exists(asc_seams):
    import re as _re
    with open(asc_seams) as _f:
      crabs_macros = _re.findall(
          r"#define\s+(CRABS_[A-Z0-9_]+)\s+(\d+)", _f.read())
  if crabs_macros:
    for macro, num in crabs_macros:
      lines.append(f"#define {macro}\t\t\t{num}")
  else:
    # Fallback: sequential CRABS_* names.
    for i in range(1, base_offset + 1):
      lines.append(f"#define CRABS_{i}\t\t\t{i}")
  # IGEEK_* project macros (base_offset+1 ..).
  for i, seam in enumerate(ordered_seams):
    num = base_offset + i + 1
    macro = seam["name"].upper()
    lines.append(f"#define {macro}\t\t\t{num}")
  # SEAM_N.
  release_macro = release_seam["name"].upper()
  lines.append(f"#define SEAM_N {release_macro}")
  # Includes: _Config.h first, then the ASCIICrabs machine.
  lines.append('#include <_Config.h>')
  lines.append('#include "../../ASCIICrabs/_Config.h"')
  lines.append('#include "../../ASCIICrabs/_Seams.hxx"')
  lines.append('#include "../../ASCIICrabs/Test.hpp"')
  # Module includes: each module's _Seams.hxx (user-owned).
  for mi in module_info:
    name = mi["name"]
    lines.append(f'#include "{name}/_Seams.hxx"')
  # Release.hxx (the release-tree rollup).
  lines.append('#include "Release.hxx"')
  lines.append("")
  lines.append("using namespace CTK;")
  lines.append("")
  lines.append("ISC main(ISC arg_count, CHA** args) {")
  lines.append("  const CHA* argss = ArgsToString(arg_count, args);")
  lines.append("  #if SEAM == SEAM_N")
  lines.append("  return SeamResult(iGeekTest::iGeekRelease(argss));")
  lines.append("  #else")
  # Test tree: CoreMain (Core module's wrapper) + each world's dispatch fn.
  nodes = []
  for mi in module_info:
    name = mi["name"]
    if name == "Core":
      nodes.append("iGeekTest::CoreMain")
    else:
      nodes.append(f"{name}Test::{name}")
  node_lines = ",\n    ".join(nodes)
  lines.append(f"  return SeamResult(TTestTree<{node_lines}\n  >(argss));")
  lines.append("  #endif")
  lines.append("}")
  lines.append("")
  return "\n".join(lines)


def SyncIgeek(project_dir, data, mode):
  """igeek-mode sync: hierarchical modules schema, scaffolding-only. Reuses
  SyncModules' module-ordering + global-numbering logic, then writes the
  igeek-shaped scaffolding files (never the user-owned test bodies)."""
  project = str(data.get("project", "PROJECT"))
  modules = data.get("modules") or []
  if not modules:
    raise SystemExit("SyncSeams: igeek mode requires a non-empty modules: list")
  for m in modules:
    if not isinstance(m, dict) or not m.get("name"):
      raise SystemExit(f"SyncSeams: a module in modules: has no name: {m}")
  release_module = str(data.get("release_module", modules[-1]["name"]))
  if modules[-1]["name"] != release_module:
    raise SystemExit(
        f"SyncSeams: release module {release_module} must be the LAST entry "
        f"in modules: (last is {modules[-1]['name']}).")

  # The ASCIICrabs base: the number of CRABS_* seams the project builds on
  # top of. iGeek = 23 (CRABS_* is 1..23). Read from the ASCIICrabs seam
  # table (the one the project's _Seams.h includes) so the iGeek block starts
  # at base+1, not 1. Fall back to the data's base_offset, else 0.
  base_offset = ISC(data.get("base_offset", 0))
  if base_offset == 0:
    # Read from _Seams.cpp first (the new self-contained TU), fall back to
    # _Seams.h (the legacy separate header).
    for cand in ("_Seams.cpp", "_Seams.h"):
      asc_seams = os.path.join(project_dir, "..", "ASCIICrabs", "_Seams", cand)
      if os.path.exists(asc_seams):
        import re as _re
        with open(asc_seams) as _f:
          _crabs = _re.findall(r"#define\s+CRABS_[A-Z0-9_]+\s+(\d+)", _f.read())
          if _crabs:
            base_offset = max(ISC(x) for x in _crabs)
            break

  # Build the global all_seams + module_info (same logic as SyncModules, but
  # igeek does NOT require the module folder to pre-exist a _Seams.yaml — it
  # only reads the seam list; the folder is where the user-owned test bodies
  # live and the per-world _Tests.hxx stub gets written).
  module_info = []
  all_seams = []
  seen = {}
  for m in modules:
    name = str(m["name"])
    folder = m.get("folder") or f"_Seams/{name}"
    if os.path.isabs(str(folder)):
      raise SystemExit(f"SyncSeams: module {name}: folder must be relative")
    folder = str(folder)
    mpath = os.path.join(project_dir, folder, "_Seams.yaml")
    if not os.path.exists(mpath):
      raise SystemExit(
          f"SyncSeams: module {name}: {os.path.relpath(mpath, project_dir)} "
          f"not found.")
    mdata = LoadSeams(mpath)
    mseams = mdata.get("seams") or []
    for s in mseams:
      s["module"] = name
    ordered_m = OrderSeams(mseams)
    for s in ordered_m:
      key = s["name"].upper()
      if key in seen:
        raise SystemExit(
            f"SyncSeams: duplicate seam name {key} (modules {seen[key]} and "
            f"{name}).")
      seen[key] = name
      all_seams.append(s)
    module_info.append({
        "name": name,
        "folder": folder,
        "seams": ordered_m,
        "dormant": BOL(m.get("dormant")),
        "mdata": mdata,
    })

  if not all_seams:
    raise SystemExit("SyncSeams: no seams found in any module")

  # Global depends validation (deps must sit strictly earlier).
  for i, s in enumerate(all_seams):
    deps = s.get("depends") or []
    if isinstance(deps, str):
      deps = [deps]
    for d in deps:
      d = str(d).upper()
      if d not in seen:
        raise SystemExit(
            f"SyncSeams: module {s['module']}: seam {s['name']} depends on "
            f"unknown seam {d}.")
      dep_idx = next(j for j, x in enumerate(all_seams)
                     if x["name"].upper() == d)
      if dep_idx >= i:
        raise SystemExit(
            f"SyncSeams: module {s['module']}: seam {s['name']} depends on "
            f"{d}, which is not earlier in the global table.")

  release_mod = next(mi for mi in module_info if mi["name"] == release_module)
  release_seam = release_mod["seams"][-1] if release_mod["seams"] \
      else all_seams[-1]

  seams_dir = os.path.join(project_dir, "_Seams")
  os.makedirs(seams_dir, exist_ok=True)
  written = []

  def Write(root, rel_path, content):
    path = os.path.join(root, rel_path)
    if os.path.dirname(path):
      os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
      f.write(content)
    written.append(os.path.relpath(path, project_dir))

  # Scaffolding files (scaffolding-only: test bodies are NOT touched).
  # The seam table + includes + main() all live in _Seams/_Seams.cpp
  # (self-contained, no separate _Seams.h). The per-module _Seams.hxx files
  # are user-owned and NOT regenerated by this sync.
  Write(seams_dir, "_Config.h",
        GenerateIgeekConfigH(project, all_seams, release_seam, base_offset))
  Write(seams_dir, "_Seams.cpp",
        GenerateIgeekSeamsCpp(project, all_seams, release_seam, base_offset,
                              module_info, project_dir))

  print(f"Synced {len(written)} files (igeek mode, base_offset={base_offset}):")
  for w in written:
    print(f"  {w}")
  print(f"\nSeam table (module order x depends; iGeek block on top of base 1..{base_offset}):")
  for i, seam in enumerate(all_seams):
    num = base_offset + i + 1
    marker = "  (release)" if seam is release_seam else ""
    print(f"  {num}. {seam['name'].upper()} = {num}  [{seam['module']}]{marker}")


# ---------------------------------------------------------------------------
# Main sync
# ---------------------------------------------------------------------------

def Sync(project_dir, yaml_path, mode, output_dir=None):
  data = LoadSeams(yaml_path)
  project = data.get("project", "PROJECT")
  if data.get("modules"):
    if mode not in ("crabstk", "igeek"):
      raise SystemExit(
          f"SyncSeams: the modules: schema requires mode: crabstk or igeek "
          f"(got {mode}).")
    if mode == "igeek":
      return SyncIgeek(project_dir, data, mode)
    if data.get("DependsOn"):
      # crabstk v2: DependsOn base (ASCIICrabs standard library) +
      # self-contained _Seams.cpp + numbered .hxx files.
      return SyncCrabstk(project_dir, data, mode, output_dir=output_dir)
    return SyncModules(project_dir, data, mode)
  seams = data.get("seams", [])
  release_name = data.get("release", seams[-1]["name"])
  ordered = OrderSeams(seams)
  release_seam = FindRelease(ordered, release_name)

  # Validate: the release seam must be the highest number.
  rel_index = ordered.index(release_seam)
  if rel_index != len(ordered) - 1:
    raise SystemExit(
        f"SyncSeams: release seam {release_seam['name']} is not last in the "
        f"ordered table (position {rel_index + 1} of {len(ordered)}).")

  seams_dir = os.path.join(project_dir, "_Seams")
  os.makedirs(seams_dir, exist_ok=True)
  written = []

  def Write(root, rel_path, content):
    path = os.path.join(root, rel_path)
    os.makedirs(os.path.dirname(path), exist_ok=True) if os.path.dirname(
        path) else None
    with open(path, "w") as f:
      f.write(content)
    written.append(os.path.relpath(path, project_dir))

  # _Seams.h -> project root (the package's seam table).
  Write(project_dir, "_Seams.h", GenerateSeamsH(project, ordered, release_seam))

  if mode == "museworld":
    # _Config.h + _Main.hxx -> project root (single TU lives in the root).
    # _Tests.hxx + per-seam .hxx -> <root>/_Seams/.
    Write(project_dir, "_Config.h",
          GenerateConfigH(project, ordered, release_seam, mode))
    Write(project_dir, "_Main.hxx",
          GenerateMainCpp(project, ordered, release_seam, mode))
    tests = GenerateTestsHxx(project, ordered, release_seam, mode)
    if tests:
      Write(seams_dir, "_Tests.hxx", tests)
    for fname, fcontent in GenerateSeamHxx(
            project, ordered, release_seam, mode).items():
      Write(seams_dir, fname, fcontent)
  else:
    Write(seams_dir, "_Seams.h",
          GenerateSeamsH(project, ordered, release_seam))
    Write(seams_dir, "_Config.h",
          GenerateConfigH(project, ordered, release_seam, mode))
    Write(seams_dir, "_Main.hxx",
          GenerateMainCpp(project, ordered, release_seam, mode))
    tests = GenerateTestsHxx(project, ordered, release_seam, mode)
    if tests:
      Write(seams_dir, "_Tests.hxx", tests)
    if mode == "asciicrabs":
      for fname, fcontent in GenerateSeamHxx(
              project, ordered, release_seam, mode).items():
        Write(seams_dir, fname, fcontent)
    else:
      # crabstk: one 01.Core.hxx per module.
      modules = {}
      for seam in ordered:
        mod = seam.get("module", project.capitalize())
        modules.setdefault(mod, []).append(seam)
      for mod, mod_seams in modules.items():
        lines = ["#pragma once", '#include <_Config.h>', ""]
        for seam in mod_seams:
          macro = seam["name"].upper()
          lines.append(f"#if SEAM == {macro}")
          lines.append('#include <ASCIICrabs/_Debug.h>')
          lines.append(f"#elif SEAM > {macro}")
          lines.append('#include <ASCIICrabs/_Release.h>')
          lines.append("#endif")
        lines.append('#include <ASCIICrabs/Test.h>')
        lines.append("")
        lines.append("using namespace CTK;")
        lines.append("namespace CTK {")
        lines.append(f"namespace {mod} {{")
        lines.append("namespace Test {")
        lines.append("")
        for seam in mod_seams:
          macro = seam["name"].upper()
          fn = TestFunctionName(project, seam["name"])
          label = seam.get("label", f"Testing {seam['name']}...")
          is_release = seam is release_seam
          lines.append(f"inline const CHA* {fn}(const CHA* args) {{")
          if is_release:
            lines.append(f"#if SEAM == {macro}")
            lines.append("#endif")
          else:
            lines.append(f"#if SEAM >= {macro}")
            lines.append("  _ATestBegin;")
            lines.append(f'  D_COUT(Headingf("{label}"));')
            lines.append("")
            lines.append("  // Your test code here.")
            lines.append("")
            lines.append("#endif")
          lines.append("  return _NilP;")
          lines.append("}")
          lines.append("")
        lines.append("}  //< namespace Test")
        lines.append(f"}}  //< namespace {mod}")
        lines.append("}  //< namespace CTK")
        lines.append("")
        Write(seams_dir, f"{mod}/01.Core.hxx", "\n".join(lines))

  print(f"Synced {len(written)} files from {os.path.basename(yaml_path)}:")
  for w in written:
    print(f"  {w}")
  print(f"\nSeam table (ordered by depends):")
  for i, seam in enumerate(ordered, 1):
    marker = "  (release)" if seam is release_seam else ""
    print(f"  {i}. {seam['name'].upper()} = {i}{marker}")


def Main():
  script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
  out_dir = None
  args = sys.argv[1:]
  if "--out" in args:
    i = args.index("--out")
    if i + 1 >= len(args):
      print("Error: --out requires a directory argument")
      return 1
    out_dir = os.path.abspath(args[i + 1])
    del args[i:i + 2]
  # --scan: autogenerate _Seams.yaml from files on disk
  if "--scan" in args:
    i = args.index("--scan")
    del args[i]
    project_dir = args[0] if args else os.path.join(script_dir, "..")
    project_dir = os.path.abspath(project_dir)
    print(f"Scanning {project_dir}/_Seams/ for numbered .hxx files...")
    yaml_text, modules = ScanSeams(project_dir)
    yaml_path = os.path.join(project_dir, "_Seams.yaml")
    with open(yaml_path, "w") as f:
      f.write(yaml_text)
    print(f"\nWrote {yaml_path} ({len(modules)} modules)")
    return 0
  if args:
    yaml_path = os.path.abspath(args[0])
  else:
    yaml_path = os.path.join(script_dir, "seams.yaml")
  if not os.path.exists(yaml_path):
    print(f"Error: {yaml_path} not found")
    return 1
  data = LoadSeams(yaml_path)
  project = data.get("project", "PROJECT")
  mode = data.get("mode", "asciicrabs")
  project_dir = data.get("project_dir", ".")
  if project_dir == ".":
    project_dir = os.path.dirname(os.path.abspath(yaml_path))
  elif not os.path.isabs(project_dir):
    project_dir = os.path.abspath(project_dir)
  print(f"Project: {project}")
  print(f"Mode:    {mode}")
  print(f"Dir:     {project_dir}")
  if out_dir:
    print(f"Out:     {out_dir}")
  print()
  Sync(project_dir, yaml_path, mode, output_dir=out_dir)
  return 0


if __name__ == "__main__":
  sys.exit(Main())
